-- Reduce repeated JWT parsing without changing any authorization predicates.
-- Fail closed if production policies or job definitions differ from the audit.
-- Cron limits are session SET statements BEFORE the job statement, not function
-- SET clauses (which would not bound the already-started statement).
SET lock_timeout = '3s';
SET statement_timeout = '30s';
DO $upgrade$
DECLARE expected record; actual record; statement text; original_command text;
BEGIN
 FOR expected IN SELECT * FROM jsonb_to_recordset($snapshot$[{"schemaname":"public","tablename":"assignments","policyname":"assignments_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"((portal_private.is_enrolled(auth.uid(), portal_private.exam_track(exam_id)) AND ((user_id = auth.uid()) OR portal_private.in_group(group_id, auth.uid()))) OR (portal_private.staff_can_touch_track(portal_private.exam_track(exam_id)) AND (portal_private.is_admin() OR ((user_id IS NOT NULL) AND portal_private.staff_can_read_student(user_id)) OR (EXISTS ( SELECT 1\n   FROM groups g\n  WHERE ((g.id = assignments.group_id) AND (g.instructor_id = auth.uid())))))))","with_check":null},{"schemaname":"public","tablename":"attempt_answers","policyname":"answers_insert_live","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"INSERT","qual":null,"with_check":"portal_private.attempt_live_for(attempt_id, auth.uid())"},{"schemaname":"public","tablename":"attempt_answers","policyname":"answers_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"(portal_private.attempt_is_mine(attempt_id, auth.uid()) OR portal_private.staff_can_read_attempt(attempt_id))","with_check":null},{"schemaname":"public","tablename":"attempt_answers","policyname":"answers_update_live","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"UPDATE","qual":"portal_private.attempt_live_for(attempt_id, auth.uid())","with_check":"portal_private.attempt_live_for(attempt_id, auth.uid())"},{"schemaname":"public","tablename":"attempt_results","policyname":"results_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"\nCASE\n    WHEN ( SELECT portal_private.is_admin() AS is_admin) THEN true\n    ELSE ((portal_private.attempt_review_open(attempt_id, auth.uid()) AND portal_private.attempt_is_mine(attempt_id, auth.uid())) OR portal_private.staff_can_read_attempt(attempt_id))\nEND","with_check":null},{"schemaname":"public","tablename":"attempts","policyname":"attempts_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"\nCASE\n    WHEN ( SELECT portal_private.is_admin() AS is_admin) THEN true\n    ELSE (((user_id = auth.uid()) AND course_history_access(auth.uid(), portal_private.exam_track(exam_id))) OR (portal_private.staff_can_touch_track(portal_private.exam_track(exam_id)) AND portal_private.staff_can_read_student(user_id)))\nEND","with_check":null},{"schemaname":"public","tablename":"daily_progress","policyname":"daily_progress_staff_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"(( SELECT portal_private.is_admin() AS is_admin) OR (portal_private.staff_can_touch_track(track_id) AND (((quiz_group_id IS NULL) AND portal_private.staff_can_read_student(user_id)) OR (EXISTS ( SELECT 1\n   FROM groups g\n  WHERE ((g.id = daily_progress.quiz_group_id) AND (g.instructor_id = auth.uid()) AND (g.track_id = daily_progress.track_id)))))))","with_check":null},{"schemaname":"public","tablename":"device_sessions","policyname":"devices_own","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"ALL","qual":"((user_id = auth.uid()) OR portal_private.is_admin())","with_check":"((user_id = auth.uid()) OR portal_private.is_admin())"},{"schemaname":"public","tablename":"enrollments","policyname":"enrollments_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"((user_id = auth.uid()) OR (portal_private.staff_can_touch_track(track_id) AND portal_private.staff_can_read_student(user_id)))","with_check":null},{"schemaname":"public","tablename":"exams","policyname":"exams_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"\nCASE\n    WHEN ( SELECT portal_private.is_admin() AS is_admin) THEN true\n    ELSE (portal_private.staff_can_touch_track(track_id) OR (is_published AND portal_private.is_enrolled(auth.uid(), track_id) AND portal_private.exam_assigned_to(id, auth.uid())))\nEND","with_check":null},{"schemaname":"public","tablename":"group_members","policyname":"group_members_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"((user_id = auth.uid()) OR portal_private.staff_can_read_student(user_id))","with_check":null},{"schemaname":"public","tablename":"groups","policyname":"groups_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"(portal_private.is_admin() OR ((instructor_id = auth.uid()) AND portal_private.staff_can_touch_track(track_id)) OR portal_private.in_group(id, auth.uid()))","with_check":null},{"schemaname":"public","tablename":"instructor_tracks","policyname":"instructor_tracks_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"((user_id = auth.uid()) OR portal_private.is_admin())","with_check":null},{"schemaname":"public","tablename":"profiles","policyname":"profiles_self_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"((id = auth.uid()) OR portal_private.staff_can_read_student(id))","with_check":null},{"schemaname":"public","tablename":"retake_grants","policyname":"retakes_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"((user_id = auth.uid()) OR portal_private.staff_can_touch_track(portal_private.exam_track(exam_id)))","with_check":null},{"schemaname":"public","tablename":"tracks","policyname":"tracks_read","permissive":"PERMISSIVE","roles":"{authenticated}","cmd":"SELECT","qual":"(portal_private.staff_can_touch_track(id) OR course_history_access(auth.uid(), id))","with_check":null}]$snapshot$::jsonb)
 AS p(schemaname text,tablename text,policyname text,permissive text,roles text,cmd text,qual text,with_check text)
 LOOP
  SELECT * INTO actual FROM pg_policies
  WHERE schemaname=expected.schemaname AND tablename=expected.tablename AND policyname=expected.policyname;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing policy %.%',expected.tablename,expected.policyname; END IF;
  IF actual.permissive IS DISTINCT FROM expected.permissive OR actual.roles::text IS DISTINCT FROM expected.roles
   OR actual.cmd IS DISTINCT FROM expected.cmd OR actual.qual IS DISTINCT FROM expected.qual
   OR actual.with_check IS DISTINCT FROM expected.with_check THEN
   RAISE EXCEPTION 'Policy changed since audit: %.%',expected.tablename,expected.policyname;
  END IF;
  statement:=format('ALTER POLICY %I ON %I.%I',expected.policyname,expected.schemaname,expected.tablename);
  IF expected.qual IS NOT NULL THEN statement:=statement||format(' USING (%s)',replace(expected.qual,'auth.uid()','(SELECT auth.uid())')); END IF;
  IF expected.with_check IS NOT NULL THEN statement:=statement||format(' WITH CHECK (%s)',replace(expected.with_check,'auth.uid()','(SELECT auth.uid())')); END IF;
  EXECUTE statement;
 END LOOP;
 FOR expected IN SELECT * FROM jsonb_to_recordset($jobs$[{"jobname":"sweep-expired-attempts","schedule":"* * * * *","command_hash":"e7a8c406ea48e362c301b5eb01a9d903","statement_timeout":"30s"},{"jobname":"portal-push-delivery","schedule":"* * * * *","command_hash":"afd205ef6f1424a9eab49368b3a5b5ef","statement_timeout":"10s"},{"jobname":"portal-weekly-algebra-assessments","schedule":"*/5 * * * *","command_hash":"6d1bbf9cf2acfb91ef84d5e46704911d","statement_timeout":"30s"}]$jobs$::jsonb)
 AS p(jobname text,schedule text,command_hash text,statement_timeout text)
 LOOP
  SELECT * INTO actual FROM cron.job WHERE jobname=expected.jobname;
  IF NOT FOUND THEN RAISE EXCEPTION 'Missing cron job: %',expected.jobname; END IF;
  IF actual.schedule IS DISTINCT FROM expected.schedule OR actual.username IS DISTINCT FROM 'postgres'
   OR actual.database IS DISTINCT FROM 'postgres' OR actual.active IS DISTINCT FROM true
   OR md5(actual.command) IS DISTINCT FROM expected.command_hash THEN
   RAISE EXCEPTION 'Cron job changed since audit: %',expected.jobname;
  END IF;
  original_command:=actual.command;
  PERFORM cron.alter_job(job_id:=actual.jobid,command:=format(
   'SET statement_timeout = %L; SET lock_timeout = ''3s''; SET idle_in_transaction_session_timeout = ''30s''; %s',
   expected.statement_timeout,original_command));
 END LOOP;
END $upgrade$;

